def validate_input(user_message: str, max_tokens: int = 4000) -> ValidationResult:
    if not user_message or not user_message.strip():
        return reject("empty_input")

    if estimate_tokens(user_message) > max_tokens:
        return reject("input_too_long")

    if contains_pii_pattern(user_message):
        # e.g. detected SSN-like or card-number-like pattern
        return reject("potential_pii", redact=True)

    if matches_injection_heuristics(user_message):
        # e.g. 'ignore previous instructions', role-override phrasing
        flag_for_review(user_message)
        # still allowed through, but logged and monitored

    if contains_blocked_terms(user_message, blocklist):
        return reject("blocked_content")

    return accept(user_message)

def resolve_model_version(user_id: str, flags: FeatureFlagClient) -> str:
    if flags.is_enabled("model-v14-killswitch"):
        return "v13"  # emergency override, ignores all targeting below

    if flags.is_enabled("model-v14-rollout", user_id=user_id):
        return "v14"

    return "v13"  # default / baseline version

